import{c as t,W as a,j as r,n as s}from"./chunks/framework.Bl84hko2.js";const u=JSON.parse('{"title":"Running a Feature","description":"","frontmatter":{"id":"guide.running-a-feature","title":"Running a Feature","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/running-a-feature.md","filePath":"guides/running-a-feature.md"}'),n={name:"guides/running-a-feature.md"};function o(i,e,h,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="running-a-feature" tabindex="-1">Running a Feature <a class="header-anchor" href="#running-a-feature" aria-label="Permalink to “Running a Feature”">​</a></h1><h2 id="what-actually-happens-from-idea-to-merged-and-what-is-your-part" tabindex="-1">What actually happens from idea to merged, and what is your part? <a class="header-anchor" href="#what-actually-happens-from-idea-to-merged-and-what-is-your-part" aria-label="Permalink to “What actually happens from idea to merged, and what is your part?”">​</a></h2><p>Follow one small feature: project members need to export a report. You describe it, shape its proposal, review a real result, and accept or return it. The agent does the branch work, implementation, checks, reviews, preview, and release preparation.</p><p>Use one command whenever you want to orient yourself:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> status</span></span></code></pre></div><p>It takes no arguments. It derives the current phase from the branch, pull request, and active proposal, then names the next actor.</p><h2 id="what-you-actually-do" tabindex="-1">What you actually do <a class="header-anchor" href="#what-you-actually-do" aria-label="Permalink to “What you actually do”">​</a></h2><ol><li>Describe the work you want done.</li><li>Iterate on the proposal until it captures the intended design.</li><li>Review the readiness report, diff, and preview.</li><li>Return it for revisions or accept it.</li></ol><p>The agent owns the work between those decisions. Comment on the pull request or commit directly to its branch; the agent reads a direct commit as instruction.</p><p>Here is the status command run in this repository while its proposal was ready for implementation:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>[status] $ node tools/status.mjs</span></span>
<span class="line"><span>proposal.0001  Workbench 2.0  ·  awaiting-implementation</span></span>
<span class="line"><span>PR #1 (draft)  https://github.com/markmals/workbench/pull/1</span></span>
<span class="line"><span>branch workbench-2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 3 — Implementation</span></span>
<span class="line"><span>  The proposal is approved for implementation.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Next (agent): Write failing tests, then guides, then code and gates. Complete cross-artifact and adversarial reviews, post the readiness report, and mark the pull request ready.</span></span>
<span class="line"><span>              Skill: .agents/skills/implementing-a-proposal/</span></span></code></pre></div><p>The exact branch, proposal, and pull-request details change. The phase and next actor are the parts to use.</p><h2 id="phase-1-—-preparation" tabindex="-1">Phase 1 — Preparation <a class="header-anchor" href="#phase-1-—-preparation" aria-label="Permalink to “Phase 1 — Preparation”">​</a></h2><h3 id="you" tabindex="-1">You <a class="header-anchor" href="#you" aria-label="Permalink to “You”">​</a></h3><p>Tell the agent: “Project members need to export a report.” Then do nothing while it creates the workspace.</p><h3 id="the-agent" tabindex="-1">The agent <a class="header-anchor" href="#the-agent" aria-label="Permalink to “The agent”">​</a></h3><p>The agent creates a branch, pushes it, and opens a draft pull request before writing the proposal or implementation.</p><p>The pull request exists this early because it is the durable workspace for one feature: its proposal, implementation, review discussion, and readiness report accumulate there as one reviewable thing.</p><h3 id="what-status-reports" tabindex="-1">What status reports <a class="header-anchor" href="#what-status-reports" aria-label="Permalink to “What status reports”">​</a></h3><p>Before a branch exists, it reports <strong>Phase 1 — Preparation</strong> and tells the agent to create one. On a feature branch without a pull request, it again reports Phase 1 and tells the agent to push the branch and open a draft pull request. You are not expected to perform either action.</p><h2 id="phase-2-—-proposal" tabindex="-1">Phase 2 — Proposal <a class="header-anchor" href="#phase-2-—-proposal" aria-label="Permalink to “Phase 2 — Proposal”">​</a></h2><h3 id="you-1" tabindex="-1">You <a class="header-anchor" href="#you-1" aria-label="Permalink to “You”">​</a></h3><p>React to the proposal until it represents the change you intend. Comment on the pull request, or edit <code>proposals/&lt;NNNN&gt;-&lt;slug&gt;.md</code> directly on the branch. Both work. This is where nearly all of the leverage is, and it can take many rounds.</p><p>Do not leave an uncertainty for the agent to infer. It records one as:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>[NEEDS CLARIFICATION: Which users can export a report?]</span></span></code></pre></div><p>Answer the question or revise the design. The marker is not permission for the agent to guess. A proposal cannot move beyond <code>draft</code> with an unresolved marker.</p><p>When the proposal is settled, you decide that it may become <code>awaiting-implementation</code>. You may ask the agent to make the edit, but the judgement remains yours. See <a href="./writing-a-good-proposal">Writing a Good Proposal</a>.</p><h3 id="the-agent-1" tabindex="-1">The agent <a class="header-anchor" href="#the-agent-1" aria-label="Permalink to “The agent”">​</a></h3><p>The agent writes <code>proposals/&lt;NNNN&gt;-&lt;slug&gt;.md</code> and pushes it as soon as it is coherent enough to react to — not after it is polished. It incorporates your comments and direct commits, preserving the durable design record.</p><h3 id="what-status-reports-1" tabindex="-1">What status reports <a class="header-anchor" href="#what-status-reports-1" aria-label="Permalink to “What status reports”">​</a></h3><p>With a draft pull request but no proposal, it reports <strong>Phase 2 — Proposal</strong> and tells the agent to write and push one. Once a <code>draft</code> proposal exists, it still reports Phase 2 and tells you to edit it or request changes. It remains <code>draft</code> for every round until you settle it.</p><h2 id="phase-3-—-implementation" tabindex="-1">Phase 3 — Implementation <a class="header-anchor" href="#phase-3-—-implementation" aria-label="Permalink to “Phase 3 — Implementation”">​</a></h2><h3 id="you-2" tabindex="-1">You <a class="header-anchor" href="#you-2" aria-label="Permalink to “You”">​</a></h3><p>Do nothing. This phase may take a long time. The agent returns with a reviewable result rather than asking you to supervise its internal sequence.</p><h3 id="the-agent-2" tabindex="-1">The agent <a class="header-anchor" href="#the-agent-2" aria-label="Permalink to “The agent”">​</a></h3><p>The order is fixed:</p><ol><li>Write failing tests for the report export the proposal specifies.</li><li>Write guides from the proposal and compare them with the tests.</li><li>Implement the code.</li><li>Run the gates with <code>mise run check</code>.</li></ol><p><code>mise run check</code> runs <code>fmt:check</code>, <code>validate</code>, <code>test</code>, and <code>docs:build</code>.</p><p>The order protects the design. Tests written after code agree with code that already exists; guides written after implementation document its accidents. Writing both from the proposal gives each an independent claim before code.</p><p>Passing the gates is not the end. Still in Phase 3, the agent reviews the proposal, tests, guides, and code together; dispatches an adversarial review to a different model; resolves valid findings; and preserves declined findings.</p><p>It then publishes the preview, posts the readiness report, and marks the pull request ready as one coupled action. That action also changes the proposal to <code>active-review</code>.</p><p>For the preview, the agent chooses the cheapest realistic artifact through which you can exercise the change — a prerelease package, preview deployment or endpoint, deployed documentation site, installable executable, or installable desktop or mobile build. See <a href="./choosing-a-preview">Choosing a Preview</a>.</p><h3 id="what-status-reports-2" tabindex="-1">What status reports <a class="header-anchor" href="#what-status-reports-2" aria-label="Permalink to “What status reports”">​</a></h3><p>Once you set <code>awaiting-implementation</code>, it reports <strong>Phase 3 — Implementation</strong> and names the agent as next. The command output above is a real example of that state. After the coupled final action, it reports <strong>Phase 4 — Human review</strong> and names you as next.</p><h2 id="phase-4-—-human-review" tabindex="-1">Phase 4 — Human review <a class="header-anchor" href="#phase-4-—-human-review" aria-label="Permalink to “Phase 4 — Human review”">​</a></h2><h3 id="you-3" tabindex="-1">You <a class="header-anchor" href="#you-3" aria-label="Permalink to “You”">​</a></h3><p>Three things arrive together: a readiness-report comment, a diff, and a preview where you can export a report. Read the report, inspect the diff, and use it.</p><p>Pay particular attention to the <strong>Declined adversarial findings</strong> section. It records findings the agent disagreed with rather than silently dropping them — the highest-signal part of the report.</p><p>Then decide. Set <code>returned-for-revisions</code> when you want changes, or <code>accepted</code> when it is good enough to complete. You may ask the agent to update the status.</p><p>Feedback that changes the design sends the proposal back to Phase 2 first. Feedback correcting only implementation returns directly to Phase 3.</p><h3 id="the-agent-3" tabindex="-1">The agent <a class="header-anchor" href="#the-agent-3" aria-label="Permalink to “The agent”">​</a></h3><p>The agent reads your comments and commits, updates the affected work, and repeats the relevant implementation and review work. It cannot accept the feature.</p><h3 id="what-status-reports-3" tabindex="-1">What status reports <a class="header-anchor" href="#what-status-reports-3" aria-label="Permalink to “What status reports”">​</a></h3><p>At <code>active-review</code>, it reports <strong>Phase 4 — Human review</strong> and tells you to review the diff and preview, then comment or accept. At <code>returned-for-revisions</code>, it reports <strong>Phase 4 → 3 — Human review → Implementation</strong>, and its next action covers the conditional case: update the proposal first if the design changed. The tool cannot know which your feedback requires, so it names the common path and leaves the judgement in the text.</p><h2 id="phase-5-—-completion-and-release" tabindex="-1">Phase 5 — Completion and release <a class="header-anchor" href="#phase-5-—-completion-and-release" aria-label="Permalink to “Phase 5 — Completion and release”">​</a></h2><h3 id="you-4" tabindex="-1">You <a class="header-anchor" href="#you-4" aria-label="Permalink to “You”">​</a></h3><p>After acceptance, explicitly confirm release and branch deletion when the agent asks. Those actions are never implied by accepting the feature.</p><h3 id="the-agent-4" tabindex="-1">The agent <a class="header-anchor" href="#the-agent-4" aria-label="Permalink to “The agent”">​</a></h3><p>If the feature changed what the project is, the agent updates <code>VISION.md</code>. It prepares merge, release, dependent-project updates where relevant, and cleanup. It merges only after acceptance and sets <code>implemented</code> only after release.</p><h3 id="what-status-reports-4" tabindex="-1">What status reports <a class="header-anchor" href="#what-status-reports-4" aria-label="Permalink to “What status reports”">​</a></h3><p>At <code>accepted</code>, it reports <strong>Phase 5 — Completion</strong> and names the agent for the vision update, merge, release, and cleanup. Once <code>implemented</code> is recorded on a merged pull request, it reports that the feature is done.</p><h2 id="status-reference" tabindex="-1">Status reference <a class="header-anchor" href="#status-reference" aria-label="Permalink to “Status reference”">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Phase</th><th>Who decides</th></tr></thead><tbody><tr><td><code>draft</code></td><td>2 — proposal</td><td>Agent</td></tr><tr><td><code>awaiting-implementation</code></td><td>3 — implementation</td><td>You</td></tr><tr><td><code>active-review</code></td><td>4 — human review</td><td>Agent</td></tr><tr><td><code>returned-for-revisions</code></td><td>4 → 3 — back to implementation</td><td>You</td></tr><tr><td><code>accepted</code></td><td>5 — completion and release</td><td>You</td></tr><tr><td><code>implemented</code></td><td>5 complete</td><td>Agent</td></tr><tr><td><code>rejected</code></td><td>closed</td><td>You</td></tr><tr><td><code>withdrawn</code></td><td>closed</td><td>Either</td></tr><tr><td><code>superseded</code></td><td>closed</td><td>Either</td></tr></tbody></table><p>“Who decides” means the judgement, not the keystroke. You can direct the agent to update a status you decided; it cannot make either approval decision alone.</p><p>A policy or decision may emerge, but neither replaces the proposal. Use <a href="./keeping-the-record">Keeping the Record</a> to decide what belongs in one.</p>`,65)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
